    73→	questionType: Question["type"];
    74→}
    75→
    76→interface QuestionDragItem {
    77→	type: "question";
    78→	id: string;
    79→}
    80→
    81→type DragItem = PaletteDragItem | QuestionDragItem;
    82→
    83→interface SurveyBuilderProps {
    84→	survey: Survey;
    85→	questions: Question[];
    86→	className?: string;
    87→}
    88→
    89→export function SurveyBuilder({
    90→	survey,
    91→	questions: initialQuestions,
    92→	className,
    93→}: SurveyBuilderProps) {
    94→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
    95→		null,
    96→	);
    97→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
    98→	const [questions, setQuestions] = useState(initialQuestions);
    99→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   100→	const [overId, setOverId] = useState<string | null>(null);
   101→	const [paletteOpen, setPaletteOpen] = useState(false);
   102→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   103→	const [dropped, setDropped] = useState(false);
   104→
   105→	// Responsive breakpoints
   106→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   107→
   108→	const queryClient = useQueryClient();
   109→
   110→	// Sync state when initialQuestions changes
   111→	useEffect(() => {
   112→		setQuestions(initialQuestions);
   113→	}, [initialQuestions]);
   114→
   115→	// Reset dropped state after animation completes
   116→	useEffect(() => {
   117→		if (dropped) {
   118→			const timer = setTimeout(() => {
   119→				setDropped(false);
   120→			}, 500);
   121→			return () => clearTimeout(timer);
   122→		}
   123→	}, [dropped]);
   124→
   125→	// Reorder mutation
   126→	const reorderMutation = useMutation(
   127→		orpc.question.reorder.mutationOptions({
   128→			onSuccess: () => {
   129→				queryClient.invalidateQueries({ queryKey: ["question"] });
   130→			},
   131→			onError: (error) => {
   132→				toast.error(error.message || "Failed to reorder questions");
   133→			},
   134→		}),
   135→	);
   136→
   137→	// DnD sensors
   138→	const sensors = useSensors(
   139→		useSensor(PointerSensor, {
   140→			activationConstraint: {
   141→				distance: 5,
   142→			},
   143→		}),
   144→		useSensor(KeyboardSensor, {
   145→			coordinateGetter: sortableKeyboardCoordinates,
   146→		}),
   147→	);
   148→
   149→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   150→	const collisionDetection: CollisionDetection = (args) => {
   151→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   152→		if (args.active.data.current?.questionType) {
   153→			const pointerCollisions = pointerWithin(args);
   154→			if (pointerCollisions.length > 0) {
   155→				return pointerCollisions;
   156→			}
   157→		}
   158→		// For canvas reordering, use closestCenter for better sortable behavior
   159→		return closestCenter(args);
   160→	};
   161→
   162→	const handleDragStart = (event: DragStartEvent) => {
   163→		setDropped(false);
   164→		const { active } = event;
   165→		const data = active.data.current;
   166→
   167→		if (data?.questionType) {
   168→			// Dragging from palette
   169→			setActiveDragItem({
   170→				type: "palette",
   171→				questionType: data.questionType as Question["type"],
   172→			});
   173→		} else {
   174→			// Dragging existing question
   175→			setActiveDragItem({
   176→				type: "question",
   177→				id: active.id as string,
   178→			});
   179→		}
   180→	};
   181→
   182→	const handleDragOver = (event: DragOverEvent) => {
   183→		const { over } = event;
   184→		setOverId(over?.id as string | null);
   185→	};
   186→
   187→	const handleDragEnd = (event: DragEndEvent) => {
   188→		const { active, over } = event;
   189→		setDropped(!!over);
   190→		setActiveDragItem(null);
   191→		setOverId(null);
   192→
   193→		if (!over) return;
   194→
   195→		// Handle cancel drop
   196→		if (over.id === "palette-cancel-zone") {
   197→			return;
   198→		}
   199→
   200→		// Handle palette drop (from question type palette) - use tracked drop index
   201→		if (active.data.current?.questionType) {
   202→			const questionType = active.data.current.questionType as Question["type"];
   203→
   204→			// Calculate insert index based on over.id
   205→			const overIndex = questions.findIndex((q) => q.id === over.id);
   206→			const insertIndex = overIndex === -1 ? questions.length : overIndex;
   207→
   208→			// Optimistic update
   209→			const tempId = `temp-${crypto.randomUUID()}`;
   210→			const mockQuestion = createMockQuestion(questionType);
   211→			const optimisticQuestion = { ...mockQuestion, id: tempId };
   212→
   213→			const optimisticQuestions = [
   214→				...questions.slice(0, insertIndex).map((q, i) => ({ ...q, order: i })),
   215→				{ ...optimisticQuestion, order: insertIndex },
   216→				...questions
   217→					.slice(insertIndex)
   218→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   219→			];
   220→
   221→			setQuestions(optimisticQuestions);
   222→			setSelectedQuestionId(tempId);
   223→
   224→			// Create question and reorder
   225→			client.question
   226→				.create({
   227→					surveyId: survey.id,
   228→					type: questionType,
   229→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   230→					order: insertIndex,
   231→				})
   232→				.then((newQuestion) => {
   233→					// Replace optimistic question with real one
   234→					setQuestions((currentQuestions) => {
   235→						const updatedQuestions = currentQuestions.map((q) =>
   236→							q.id === tempId ? newQuestion : q,
   237→						);
   238→						return updatedQuestions;
   239→					});
   240→
   241→					setSelectedQuestionId((currentId) =>
   242→						currentId === tempId ? newQuestion.id : currentId,
   243→					);
   244→
   245→					queryClient.invalidateQueries({ queryKey: ["question"] });
   246→
   247→					// Reorder all questions on backend to ensure consistency
   248→					const finalQuestions = [
   249→						...questions
   250→							.slice(0, insertIndex)
   251→							.map((q, i) => ({ ...q, order: i })),
   252→						{ ...newQuestion, order: insertIndex },
   253→						...questions
   254→							.slice(insertIndex)
   255→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   256→					];
   257→
   258→					reorderMutation.mutate({
   259→						questions: finalQuestions.map((q) => ({
   260→							id: q.id,
   261→							order: q.order,
   262→						})),
   263→					});
   264→
   265→					toast.success("Question added");
   266→				})
   267→				.catch((error: Error) => {
   268→					// Revert on error
   269→					setQuestions(questions);
   270→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   271→					toast.error(error.message || "Failed to create question");
   272→				});
   273→
   274→			return;
   275→		}
   276→
   277→		// Handle reordering
   278→		if (active.id !== over.id && over.id !== "canvas") {
   279→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   280→			const newIndex = questions.findIndex((q) => q.id === over.id);
   281→
   282→			if (oldIndex !== -1 && newIndex !== -1) {
   283→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   284→					(q, index) => {
   285→						// Only create new object if order actually changed
   286→						if (q.order === index) {
   287→							return q; // Preserve reference
   288→						}
   289→						return { ...q, order: index };
   290→					},
   291→				);
   292→
   293→				setQuestions(newQuestions);
   294→
   295→				reorderMutation.mutate({
   296→					questions: newQuestions.map((q) => ({
   297→						id: q.id,
   298→						order: q.order,
   299→					})),
   300→				});
   301→			}
   302→		}
   303→	};
   304→
   305→	const contextValue: SurveyBuilderContextValue = {
   306→		survey,
   307→		questions,
   308→		selectedQuestionId,
   309→		setSelectedQuestionId,
   310→		activeTab,
   311→		setActiveTab,
   312→		onQuestionsChange: setQuestions,
   313→		paletteOpen,
   314→		setPaletteOpen,
   315→		propertiesOpen,
   316→		setPropertiesOpen,
   317→	};
   318→
   319→	const safeQuestions = questions || [];
   320→
   321→	// Render drag overlay
   322→	const renderDragOverlay = () => {
   323→		if (!activeDragItem) return null;
   324→
   325→		if (activeDragItem.type === "palette") {
   326→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
   327→			return (
   328→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   329→					<QuestionCardContent
   330→						question={mockQuestion}
   331→						isSelected={false}
   332→						hasLogic={false}
   333→						isOverlay={true}
   334→					/>
   335→				</div>
   336→			);
   337→		}
   338→
   339→		// Dragging existing question
   340→		const activeQuestion = safeQuestions.find(
   341→			(q) => q.id === activeDragItem.id,
   342→		);
   343→		if (activeQuestion) {
   344→			return (
   345→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   346→					<QuestionCardContent
   347→						question={activeQuestion}
   348→						isSelected={selectedQuestionId === activeQuestion.id}
   349→						hasLogic={false}
   350→						isOverlay={true}
   351→					/>
   352→				</div>
   353→			);
   354→		}
   355→
   356→		return null;
   357→	};
   358→
   359→	return (
   360→		<SurveyBuilderContext.Provider value={contextValue}>
   361→			<DndContext
   362→				sensors={sensors}
   363→				collisionDetection={collisionDetection}
   364→				onDragStart={handleDragStart}
   365→				onDragOver={handleDragOver}
   366→				onDragEnd={handleDragEnd}
   367→			>
   368→				<div className={cn("flex h-full flex-col", className)}>
   369→					<BuilderHeader
   370→						leftActions={
   371→							!isDesktop &&
   372→							activeTab === "build" && (
   373→								<div className="flex items-center gap-1">
   374→									<Button
   375→										variant="ghost"
   376→										size="icon"
   377→										onClick={() => setPaletteOpen(!paletteOpen)}
   378→									>
   379→										<PanelLeftClose className="h-4 w-4" />
   380→									</Button>
   381→								</div>
   382→							)
   383→						}
   384→						rightActions={
   385→							!isDesktop &&
   386→							activeTab === "build" && (
   387→								<div className="flex items-center gap-1">
   388→									<Button
   389→										variant="ghost"
   390→										size="icon"
   391→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   392→									>
   393→										<PanelRightClose className="h-4 w-4" />
   394→									</Button>
   395→								</div>
   396→							)
   397→						}
   398→					/>
   399→					<div className="flex flex-1 overflow-hidden">
   400→						{/* Left Palette - Responsive */}
   401→						{activeTab === "build" && (
   402→							<>
   403→								{/* Desktop: Fixed sidebar */}
   404→								{isDesktop && <QuestionPalette />}
   405→
   406→								{/* Tablet/Mobile: Sheet overlay */}
   407→								{!isDesktop && (
   408→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   409→										<SheetContent side="left" className="w-72 p-0">
   410→											<QuestionPalette />
   411→										</SheetContent>
   412→									</Sheet>
   413→								)}
   414→							</>
   415→						)}
   416→
   417→						{/* Canvas */}
   418→						<BuilderCanvas
   419→							questions={questions}
   420→							onQuestionsChange={setQuestions}
   421→							activeDragItem={activeDragItem}
   422→							overId={overId}
   423→							dropped={dropped}
   424→						/>
   425→
   426→						{/* Right Properties Panel - Responsive */}
   427→						{activeTab === "build" && (
   428→							<>
   429→								{/* Desktop: Fixed sidebar */}
   430→								{isDesktop && <PropertiesPanel />}
   431→
   432→								{/* Tablet/Mobile: Sheet overlay */}
   433→								{!isDesktop && (
   434→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   435→										<SheetContent side="right" className="w-80 p-0">
   436→											<PropertiesPanel />
   437→										</SheetContent>
   438→									</Sheet>
   439→								)}
   440→							</>
   441→						)}
   442→					</div>
   443→				</div>
   444→
   445→				<DragOverlay dropAnimation={dropped ? null : defaultDropAnimation}>
   446→					{renderDragOverlay()}
   447→				</DragOverlay>
   448→			</DndContext>
   449→		</SurveyBuilderContext.Provider>
   450→	);
   451→}
   452→
   453→export { BuilderCanvas } from "./builder-canvas";
   454→// Re-export sub-components for compound pattern
   455→export { BuilderHeader } from "./builder-header";
   456→export { PropertiesPanel } from "./properties-panel";
   457→export { QuestionPalette } from "./question-palette";
   458→

