"use client";

import { useDroppable } from "@dnd-kit/core";
import {
	type AnimateLayoutChanges,
	defaultAnimateLayoutChanges,
	useSortable,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { Question } from "@orksys-survey/db";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { motion } from "framer-motion";
import {
	Bolt,
	Calendar,
	CheckSquare,
	ChevronsUpDown,
	ClipboardList,
	FileText,
	GripVertical,
	Hash,
	ListChecks,
	Mail,
	Phone,
	Star,
	Text,
	Trash2,
	TrendingUp,
	X,
} from "lucide-react";
import { memo, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { orpc } from "@/utils/orpc";

export const questionTypeIcons: Record<string, React.ElementType> = {
	text: Text,
	textarea: FileText,
	multiple_choice: CheckSquare,
	checkbox: ListChecks,
	dropdown: ChevronsUpDown,
	rating: Star,
	nps: TrendingUp,
	linear_scale: Hash,
	date: Calendar,
	email: Mail,
	phone: Phone,
	file_upload: ClipboardList,
};

export const questionTypeLabels: Record<string, string> = {
	text: "Short Text",
	textarea: "Long Text",
	multiple_choice: "Multiple Choice",
	checkbox: "Checkboxes",
	dropdown: "Dropdown",
	rating: "Rating",
	nps: "NPS",
	linear_scale: "Linear Scale",
	date: "Date",
	email: "Email",
	phone: "Phone",
	file_upload: "File Upload",
};

interface QuestionCardContentProps {
	question: Question;
	isSelected?: boolean;
	hasLogic?: boolean;
	onSelect?: () => void;
	onDelete?: () => void;
	isDeleting?: boolean;
	dragHandleProps?: any;
	isDragging?: boolean;
	isOver?: boolean;
	isOverlay?: boolean;
	isPlaceholder?: boolean;
}

export function QuestionCardContent({
	question,
	isSelected,
	hasLogic,
	onSelect,
	onDelete,
	isDeleting,
	dragHandleProps,
	isDragging,
	isOver,
	isOverlay,
	isPlaceholder: explicitIsPlaceholder,
}: QuestionCardContentProps) {
	const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
	const Icon = questionTypeIcons[question.type] || Text;
	const isPlaceholder = explicitIsPlaceholder || (isDragging && !isOverlay);

	return (
		<Card
			className={cn(
				"group cursor-pointer gap-0 p-0 transition-all",
				!isSelected &&
					!isOverlay &&
					!isPlaceholder &&
					"hover:border-violet-300 hover:bg-violet-50/30",
				isSelected &&
					!isPlaceholder &&
					"border-violet-500 ring-1 ring-violet-500",
				isPlaceholder &&
					"border-2 border-violet-400 border-dashed bg-violet-50 opacity-100 shadow-none ring-0",
				isOverlay &&
					"cursor-grabbing bg-white shadow-xl ring-2 ring-violet-500",
			)}
			onClick={onSelect}
		>
			<CardContent
				className={cn(
					"flex items-start gap-3 p-4",
					isPlaceholder && "opacity-0",
				)}
			>
				<button
					type="button"
					className={cn(
						"mt-1 touch-none",
						isOverlay ? "cursor-grabbing" : "cursor-grab",
					)}
					{...dragHandleProps}
				>
					<GripVertical className="h-4 w-4 text-neutral-400" />
				</button>

				<motion.div
					className="flex h-7 w-7 shrink-0 items-center justify-center rounded bg-violet-100"
					whileHover={{ scale: 1.05 }}
					transition={{ type: "spring", stiffness: 400, damping: 17 }}
				>
					<Icon className="h-4 w-4 text-violet-600" />
				</motion.div>

				<div className="min-w-0 flex-1">
					<div className="flex items-center gap-2">
						<h3 className="truncate font-medium text-sm">{question.title}</h3>
						{question.required && (
							<motion.span
								initial={{ scale: 0 }}
								animate={{ scale: 1 }}
								className="text-red-500"
							>
								*
							</motion.span>
						)}
						{hasLogic && (
							<motion.span
								initial={{ opacity: 0, scale: 0.8 }}
								animate={{ opacity: 1, scale: 1 }}
								className="flex items-center gap-1 rounded bg-violet-100 px-1.5 py-0.5 font-medium text-[10px] text-violet-600"
							>
								<Bolt className="h-3 w-3" />
								Logic
							</motion.span>
						)}
					</div>
					<p className="mt-0.5 text-neutral-500 text-xs">
						{questionTypeLabels[question.type]}
						{question.description &&
							` • ${question.description.slice(0, 50)}${question.description.length > 50 ? "..." : ""}`}
					</p>
				</div>

				{!isOverlay &&
					onDelete &&
					(showDeleteConfirm ? (
						<div className="flex shrink-0 items-center gap-1">
							<Button
								variant="ghost"
								size="icon"
								className="h-7 w-7"
								onClick={(e) => {
									e.stopPropagation();
									setShowDeleteConfirm(false);
								}}
							>
								<X className="h-4 w-4" />
							</Button>
							<Button
								variant="ghost"
								size="icon"
								className="h-7 w-7 text-red-600 hover:bg-red-50 hover:text-red-700"
								onClick={(e) => {
									e.stopPropagation();
									onDelete();
								}}
								disabled={isDeleting}
							>
								<Trash2 className="h-4 w-4" />
							</Button>
						</div>
					) : (
						<Button
							variant="ghost"
							size="icon"
							className="h-7 w-7 shrink-0 opacity-0 transition-opacity group-hover:opacity-100 data-[selected=true]:opacity-100"
							data-selected={isSelected}
							onClick={(e) => {
								e.stopPropagation();
								setShowDeleteConfirm(true);
							}}
						>
							<Trash2 className="h-4 w-4" />
						</Button>
					))}
			</CardContent>
		</Card>
	);
}

interface QuestionCardProps {
	question: Question;
	isSelected: boolean;
	onSelect: () => void;
	questions: Question[];
	onQuestionsChange: (questions: Question[]) => void;
}

const animateLayoutChanges: AnimateLayoutChanges = (args) => {
	const { isSorting, wasDragging } = args;

	if (isSorting || wasDragging) {
		return defaultAnimateLayoutChanges(args);
	}

	return false;
};

export const QuestionCard = memo(function QuestionCard({
	question,
	isSelected,
	onSelect,
	questions,
	onQuestionsChange,
}: QuestionCardProps) {
	const queryClient = useQueryClient();

	// Sortable for reordering within canvas
	const {
		attributes,
		listeners,
		setNodeRef: setSortableRef,
		transform,
		transition,
		isDragging,
	} = useSortable({
		id: question.id,
		animateLayoutChanges,
	});

	// Droppable for palette item drops
